    settings_notifications_label: "Reminder Notifications", settings_notifications_btn_enable: "🔔 Enable", settings_notifications_btn_enabled: "🔔 Enabled", settings_notifications_btn_blocked: "🔕 Blocked",
    settings_notifications_status_default: "Turn this on so reminders alert you even when the app is closed.", settings_notifications_status_granted: "Enabled - reminders will alert you even when the app is closed.", settings_notifications_status_denied: "Notifications are blocked for this app in your browser/phone settings. Open Settings > Notifications (or the site settings in your browser) and allow notifications for Obeko, then reopen the app.", settings_notifications_status_unsupported: "This browser doesn't support background notifications.",
