    auth_forgot_password_link: "¿Olvidaste tu contraseña?", auth_back_to_login: "Volver al inicio de sesión", auth_forgot_subtitle: "Ingresa tu correo y te enviaremos un enlace para restablecerla:", auth_forgot_submit_btn: "Enviar enlace de restablecimiento", auth_fill_email: "Por favor ingresa tu correo", auth_forgot_success: "Si ese correo existe, un enlace de restablecimiento está en camino - revisa tu bandeja de entrada.",
