    habits_title: "Hábitos", habits_empty_hint: "Ainda não há hábitos - adicione um para começar a acompanhar sua sequência.", habits_add_modal_title: "Novo hábito", habits_name_placeholder: "ex. Beber água, Ler, Meditar...", habits_missing_name: "Por favor, dê um nome ao hábito",
