    nav_myweek: "我的一周",
    hamburger_menu_btn_title: "菜单", hamburger_menu_title: "菜单", hamburger_group_notes: "清单", hamburger_group_goals: "目标与进度", hamburger_group_nutrition: "营养与指标", hamburger_group_finance: "收支", hamburger_group_sport: "运动", hamburger_group_other: "其他",
    sport_add_title: "记录锻炼", sport_type_running: "🏃 跑步", sport_type_cycling: "🚴 骑行", sport_type_swimming: "🏊 游泳", sport_type_custom: "✨ 其他",
    sport_custom_type_placeholder: "什么运动？（例如瑜伽、网球）", sport_duration_placeholder: "时长（分钟）", sport_distance_placeholder: "距离（公里）- 可选",
